        Point(-1052.45, 3454.28),
        Point(-1010.03, 3369.42),
        Point(-967.602, 3327),
        Point(-925.175, 3284.57),
        Point(-840.323, 3242.14),
        Point(-755.47, 3199.72),
        Point(-670.617, 3242.14),
        Point(-585.764, 3284.57),
        Point(-543.338, 3327),
        Point(-500.911, 3369.42),
        Point(-458.485, 3454.28),
        Point(1846.26, 10000),
        Point(-3647.14, 10000)
    };

    // Gi polygon
    std::vector<Point> Gi = {
        Point(-1052.45, 3454.28),
        Point(-1010.03, 3369.42),
        Point(-967.602, 3327),
        Point(-925.175, 3284.57),
        Point(-840.323, 3242.14),
        Point(-755.47, 3199.72),
        Point(-670.617, 3242.14),
        Point(-585.764, 3284.57),
        Point(-543.338, 3327),
        Point(-500.911, 3369.42),
        Point(-458.485, 3454.28),
        Point(-458.485, 3539.13),
        Point(-500.911, 3623.98),
        Point(-543.338, 3666.41),
        Point(-585.764, 3708.83),
        Point(-670.617, 3751.26),
        Point(-755.47, 3793.69),
        Point(-840.323, 3751.26),
        Point(-925.175, 3708.83),
        Point(-967.602, 3666.41),
        Point(-1010.03, 3623.98),
        Point(-1052.45, 3539.13)
    };

    Polygon F_poly(F.begin(), F.end());
    Polygon Gi_poly(Gi.begin(), Gi.end());

    std::cout << "Using Epeck kernel (exact)" << std::endl;
    std::cout << "F is_simple: " << F_poly.is_simple() << std::endl;
    std::cout << "Gi is_simple: " << Gi_poly.is_simple() << std::endl;
    std::cout << "F orientation: " << (F_poly.is_counterclockwise_oriented() ? "CCW" : "CW") << std::endl;
    std::cout << "Gi orientation: " << (Gi_poly.is_counterclockwise_oriented() ? "CCW" : "CW") << std::endl;

    std::vector<Polygon_with_holes> result;
    CGAL::intersection(F_poly, Gi_poly, std::back_inserter(result));

    std::cout << "Intersection succeeded, result size: " << result.size() << std::endl;

    return 0;
}

// Test the exact tolerance issue
#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/Simple_cartesian.h>
#include <CGAL/Segment_2.h>
#include <iostream>
#include <vector>
#include <cmath>

using Kernel = CGAL::Simple_cartesian<double>;
using Point = Kernel::Point_2;
using Segment = Kernel::Segment_2;

int main() {
    // Test a segment on the boundary
    Point p1(-1052.45, 3454.28);
    Point p2(1846.26, 10000.0);  // This is on y=10000

    // Another segment that should intersect
    Point q1(-1052.45, 3454.28);
    Point q2(-1052.45, 3539.13);  // Vertical line at x=-1052.45

    Segment seg1(p1, p2);
    Segment seg2(q1, q2);

    std::cout << "seg1: (" << seg1.source().x() << "," << seg1.source().y() 
              << ") -> (" << seg1.target().x() << "," << seg1.target().y() << ")" << std::endl;
    std::cout << "seg2: (" << seg2.source().x() << "," << seg2.source().y() 
              << ") -> (" << seg2.target().x() << "," << seg2.target().y() << ")" << std::endl;

    // Try to intersect
    auto result = CGAL::intersection(seg1, seg2);

    if (result) {
        if (const Point* ip = std::get_if<Point>(&*result)) {
            std::cout << "Intersection point: (" << ip->x() << ", " << ip->y() << ")" << std::endl;
            std::cout << "y > 10000? " << (ip->y() > 10000.0 ? "YES" : "NO") << std::endl;
            std::cout << "y - 10000 = " << (ip->y() - 10000.0) << std::endl;
        }
    } else {
        std::cout << "No intersection" << std::endl;
    }

    return 0;
}

