// Check for collinear vertices and self-intersections
#include <CGAL/Polygon_2.h>
#include <CGAL/Simple_cartesian.h>
#include <iostream>
#include <vector>
#include <cmath>

using Kernel = CGAL::Simple_cartesian<double>;
using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;

bool is_collinear(const Point& a, const Point& b, const Point& c) {
    // Check if b is collinear with a and c
    double cross = (b.x() - a.x()) * (c.y() - a.y()) - (b.y() - a.y()) * (c.x() - a.x());
    return std::abs(cross) < 1e-10;
}

int main() {
    std::vector<Point> F = {
        Point(-1052.45, 3454.28),
        Point(-1010.03, 3369.42),
        Point(-967.602, 3327),
        Point(-925.175, 3284.57),
        Point(-840.323, 3242.14),
        Point(-755.47, 3199.72),
        Point(-670.617, 3242.14),
        Point(-585.764, 3284.57),
        Point(-543.338, 3327),
        Point(-500.911, 3369.42),
        Point(-458.485, 3454.28),
        Point(1846.26, 10000),
        Point(-3647.14, 10000)
    };

    Polygon F_poly(F.begin(), F.end());

    std::cout << "Checking F polygon for issues:" << std::endl;
    std::cout << "  is_simple: " << F_poly.is_simple() << std::endl;
    std::cout << "  size: " << F.size() << std::endl;

    // Check for collinear vertices
    std::cout << "\nCollinear vertex checks:" << std::endl;
    for (size_t i = 0; i < F.size(); i++) {
        const Point& a = F[i];
        const Point& b = F[(i + 1) % F.size()];
        const Point& c = F[(i + 2) % F.size()];

        if (is_collinear(a, b, c)) {
            std::cout << "  Vertex " << (i+1) << " (" << b.x() << "," << b.y() 
                      << ") is collinear with neighbors" << std::endl;
        }
    }

    // Check if edges on bounding box are properly formed
    std::cout << "\nEdges involving y=10000:" << std::endl;
    for (size_t i = 0; i < F.size(); i++) {
        const Point& p = F[i];
        if (std::abs(p.y() - 10000.0) < 1e-6) {
            size_t j = (i + 1) % F.size();
            const Point& q = F[j];
            std::cout << "  Edge " << i << "-" << j << ": (" << p.x() << "," << p.y() 
                      << ") -> (" << q.x() << "," << q.y() << ")";
            if (std::abs(q.y() - 10000.0) < 1e-6) {
                std::cout << " [horizontal on bbox edge]";
            }
            std::cout << std::endl;
        }
    }

    // Check if the two y=10000 vertices are consecutive
    int idx1 = -1, idx2 = -1;
    for (size_t i = 0; i < F.size(); i++) {
        if (std::abs(F[i].y() - 10000.0) < 1e-6) {
            if (idx1 == -1) idx1 = i;
            else idx2 = i;
        }
    }

    if (idx1 != -1 && idx2 != -1) {
        int dist1 = (idx2 - idx1 + F.size()) % F.size();
        int dist2 = (idx1 - idx2 + F.size()) % F.size();
        std::cout << "\nVertices at y=10000: indices " << idx1 << " and " << idx2 << std::endl;
        std::cout << "  Distance from idx1 to idx2: " << dist1 << " edges" << std::endl;
        std::cout << "  Distance from idx2 to idx1: " << dist2 << " edges" << std::endl;

        if (dist1 == 1 || dist2 == 1) {
            std::cout << "  These vertices are consecutive in the polygon!" << std::endl;
        }
    }

    return 0;
}

