// Verify Gi is non-convex
#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/convex_hull_2.h>
#include <CGAL/Simple_cartesian.h>
#include <iostream>
#include <vector>
#include <cmath>

using Kernel = CGAL::Simple_cartesian<double>;
using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;

const double DELTA = 200;
const double EPSILON = 0.6;
double R_val() { return (1.0 + EPSILON / 2.0) * DELTA; }
double GRID_val() { return EPSILON * DELTA / (2 * sqrt(2)); }

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    const double GRID = GRID_val();
    const double r2 = r * r;
    int y_min = -(r / GRID) - 1;
    int y_max = -y_min;
    std::vector<Point> boundaries;
    boundaries.reserve(2 * y_max + 1);
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px + x_min * GRID, py + y_actual);
    }
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_max = (sqrt(r2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0)
            boundaries.emplace_back(px + x_max * GRID, py + y_actual);
    }
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(), std::back_inserter(conv));
    return conv;
}

bool is_convex(const std::vector<Point>& pts) {
    int n = pts.size();
    if (n < 3) return true;
    for (int i = 0; i < n; i++) {
        const Point& a = pts[i];
        const Point& b = pts[(i + 1) % n];
        const Point& c = pts[(i + 2) % n];
        if (CGAL::orientation(a, b, c) != CGAL::LEFT_TURN) {
            return false;
        }
    }
    return true;
}

int main() {
    std::cout << "DELTA = " << DELTA << std::endl;
    std::cout << "EPSILON = " << EPSILON << std::endl;
    std::cout << "R_val() = " << R_val() << std::endl;
    std::cout << "GRID_val() = " << GRID_val() << std::endl;

    // pi = (-755.47, 3496.7) from the failing case
    Point pi(-755.47, 3496.7);

    std::vector<Point> Gi = get_conv_from_grid(pi);

    std::cout << "\nGi has " << Gi.size() << " vertices" << std::endl;
    std::cout << "is_convex: " << is_convex(Gi) << std::endl;

    Polygon poly(Gi.begin(), Gi.end());
    std::cout << "poly.is_simple(): " << poly.is_simple() << std::endl;

    // Count orientations
    int left = 0, right = 0, collinear = 0;
    for (size_t i = 0; i < Gi.size(); i++) {
        const Point& a = Gi[i];
        const Point& b = Gi[(i + 1) % Gi.size()];
        const Point& c = Gi[(i + 2) % Gi.size()];
        auto ori = CGAL::orientation(a, b, c);
        if (ori == CGAL::LEFT_TURN) left++;
        else if (ori == CGAL::RIGHT_TURN) {
            right++;
            std::cout << "RIGHT turn at vertex " << (i+1) << ": (" << b.x() << "," << b.y() << ")" << std::endl;
        }
        else collinear++;
    }
    std::cout << "Left: " << left << ", Right: " << right << ", Collinear: " << collinear << std::endl;

    return 0;
}

// MVP: Minimal reproduction of CGAL intersection bug with Simple_cartesian
// This demonstrates that the intersection fails with specific polygons
// that have vertices on the bounding box boundary.

#include <CGAL/Polygon_2.h>
