// Custom error handler with stack trace
void custom_error_handler(const char* expr, const char* file, const char* expl, int line, const char* msg) {
    std::cerr << "\n!!! CGAL ASSERTION !!!" << std::endl;
    std::cerr << "Expr: " << expr << std::endl;
    std::cerr << "File: " << file << ":" << line << std::endl;
    std::cerr << "Explanation: " << (expl ? expl : "none") << std::endl;
    std::cerr << "Message: " << msg << std::endl;

    // Print stack trace
    void* buffer[100];
    int n = backtrace(buffer, 100);
    char** strings = backtrace_symbols(buffer, n);
    std::cerr << "\nStack trace:" << std::endl;
    for (int i = 0; i < n; i++) {
        std::cerr << "  " << i << ": " << strings[i] << std::endl;
    }
    free(strings);

    // Continue instead of aborting to see more info
    std::cerr << "Continuing..." << std::endl;
}

int main() {
    // Set custom error handler
    CGAL::set_error_handler(custom_error_handler);
    CGAL::set_error_behaviour(CGAL::CONTINUE);

