// Test 2: Performance
template<typename Kernel>
double test_performance(int iterations = 1000) {
    using Point = typename Kernel::Point_2;
    using Polygon = CGAL::Polygon_2<Kernel>;
    using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

    // Simple test polygons
    std::vector<Point> A = {
        Point(0, 0), Point(100, 0), Point(100, 100), Point(0, 100)
    };
    std::vector<Point> B = {
        Point(50, 50), Point(150, 50), Point(150, 150), Point(50, 150)
    };

    Polygon A_poly(A.begin(), A.end());
    Polygon B_poly(B.begin(), B.end());

    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < iterations; i++) {
        std::vector<Polygon_with_holes> result;
        CGAL::intersection(A_poly, B_poly, std::back_inserter(result));
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
    return duration.count() / 1000.0; // ms
}

