    for (auto it = poly.vertices_begin(); it != poly.vertices_end(); ++it) {
        std::cout << "(" << *it << ") ";
    }
    std::cout << std::endl;

    // Test to_double conversion
    std::cout << "  to_double: ";
    for (auto it = poly.vertices_begin(); it != poly.vertices_end(); ++it) {
        std::cout << "(" << CGAL::to_double(it->x()) << "," << CGAL::to_double(it->y()) << ") ";
    }
    std::cout << std::endl;
}

